import{_ as t,a0 as o,w as d,s as r,ao as l,I as i,a1 as e,A as p,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何強制用户在下次登錄 Linux 時更改密碼 | LCTT x X-CMD","titleTemplate":false,"description":"如何強制用户在下次登錄 Linux 時更改密碼 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何強制用户在下次登錄 Linux 時更改密碼 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何強制用户在下次登錄 Linux 時更改密碼 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180718 How To Force User To Change Password On Next Login In Linux","title":"如何強制用户在下次登錄 Linux 時更改密碼","tag":"201807","desc":""},"relativePath":"201807/20180718 How To Force User To Change Password On Next Login In Linux.md","filePath":"[post].md"}'),h={name:"201807/20180718 How To Force User To Change Password On Next Login In Linux.md"};function u(c,s,g,w,k,m){const n=o("Link");return d(),r("div",null,[s[19]||(s[19]=l('<h1 id="如何強制用户在下次登錄-linux-時更改密碼" tabindex="-1">如何強制用户在下次登錄 Linux 時更改密碼 <a class="header-anchor" href="#如何強制用户在下次登錄-linux-時更改密碼" aria-label="Permalink to “如何強制用户在下次登錄 Linux 時更改密碼”">​</a></h1><p>當你使用默認密碼創建用户時，你必須強制用户在下一次登錄時更改密碼。</p><p>當你在一個組織中工作時，此選項是強制性的。因為老員工可能知道默認密碼，他們可能會也可能不會嘗試不當行為。</p><p>這是安全投訴之一，所以，確保你必須以正確的方式處理此事而無任何失誤。即使是你的團隊成員也要一樣做。</p><p>大多數用户都很懶，除非你強迫他們更改密碼，否則他們不會這樣做。所以要做這個實踐。</p><p>出於安全原因，你需要經常更改密碼，或者至少每個月更換一次。</p><p>確保你使用的是難以猜測的密碼（大小寫字母，數字和特殊字符的組合）。它至少應該為 10-15 個字符。</p><p>我們運行了一個 shell 腳本來在 Linux 服務器中創建一個用户賬户，它會自動為用户附加一個密碼，密碼是實際用户名和少量數字的組合。</p><p>我們可以通過使用以下兩種方法來實現這一點：</p><ul><li>passwd 命令</li><li>chage 命令</li></ul><p><strong>建議閲讀：</strong></p>',11)),i("ul",null,[i("li",null,[e(n,{href:"https://www.2daygeek.com/how-to-check-which-groups-a-user-belongs-to-on-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("如何在 Linux 上檢查用户所屬的組",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://www.2daygeek.com/how-to-check-user-created-date-on-linux/"},{default:p(()=>[...s[1]||(s[1]=[a("如何在 Linux 上檢查創建用户的日期",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://www.2daygeek.com/passwd-command-examples/"},{default:p(()=>[...s[2]||(s[2]=[a("如何在 Linux 中重置/更改用户密碼",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://www.2daygeek.com/passwd-command-examples-part-l/"},{default:p(()=>[...s[3]||(s[3]=[a("如何使用 passwd 命令管理密碼過期和老化",-1)])]),_:1})])]),s[20]||(s[20]=l(`<h3 id="方法-1-使用-passwd-命令" tabindex="-1">方法 1：使用 passwd 命令 <a class="header-anchor" href="#方法-1-使用-passwd-命令" aria-label="Permalink to “方法 1：使用 passwd 命令”">​</a></h3><p><code>passwd</code> 的意思是“密碼”。它用於更新用户的身份驗證令牌。<code>passwd</code> 命令/實用程序用於設置、修改或更改用户的密碼。</p><p>普通的用户只能更改自己的賬户，但超級用户可以更改任何賬户的密碼。</p><p>此外，我們還可以使用其他選項，允許用户執行其他活動，例如刪除用户密碼、鎖定或解鎖用户賬户、設置用户賬户的密碼過期時間等。</p><p>在 Linux 中這可以通過調用 Linux-PAM 和 Libuser API 執行。</p><p>在 Linux 中創建用户時，用户詳細信息將存儲在 <code>/etc/passwd</code> 文件中。<code>passwd</code> 文件將每個用户的詳細信息保存為帶有七個字段的單行。</p><p>此外，在 Linux 系統中創建新用户時，將更新以下四個文件。</p><ul><li><code>/etc/passwd</code>： 用户詳細信息將在此文件中更新。</li><li><code>/etc/shadow</code>： 用户密碼信息將在此文件中更新。</li><li><code>/etc/group</code>： 新用户的組詳細信息將在此文件中更新。</li><li><code>/etc/gshadow</code>： 新用户的組密碼信息將在此文件中更新。</li></ul><h4 id="如何使用-passwd-命令執行此操作" tabindex="-1">如何使用 passwd 命令執行此操作 <a class="header-anchor" href="#如何使用-passwd-命令執行此操作" aria-label="Permalink to “如何使用 passwd 命令執行此操作”">​</a></h4><p>我們可以使用 <code>passwd</code> 命令並添加 <code>-e</code> 選項來執行此操作。</p><p>為了測試這一點，讓我們創建一個新用户賬户，看看它是如何工作的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -c &quot;2g Admin - Magesh M&quot; magesh &amp;&amp; passwd magesh</span></span>
<span class="line"><span>Changing password for user magesh.</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span></code></pre></div><p>使用户賬户的密碼失效，那麼在下次登錄嘗試期間，用户將被迫更改密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># passwd -e magesh</span></span>
<span class="line"><span>Expiring password for user magesh.</span></span>
<span class="line"><span>passwd: Success</span></span></code></pre></div><p>當我第一次嘗試使用此用户登錄系統時，它要求我設置一個新密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>login as: magesh</span></span>
<span class="line"><span>[email protected]&#39;s password:</span></span>
<span class="line"><span>You are required to change your password immediately (root enforced)</span></span>
<span class="line"><span>WARNING: Your password has expired.</span></span>
<span class="line"><span>You must change your password now and login again!</span></span>
<span class="line"><span>Changing password for user magesh.</span></span>
<span class="line"><span>Changing password for magesh.</span></span>
<span class="line"><span>(current) UNIX password:</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span>
<span class="line"><span>Connection to localhost closed.</span></span></code></pre></div><h3 id="方法-2-使用-chage-命令" tabindex="-1">方法 2：使用 chage 命令 <a class="header-anchor" href="#方法-2-使用-chage-命令" aria-label="Permalink to “方法 2：使用 chage 命令”">​</a></h3><p><code>chage</code> 意即“改變時間”。它會更改用户密碼過期信息。</p><p><code>chage</code> 命令會改變上次密碼更改日期之後需要修改密碼的天數。系統使用此信息來確定用户何時必須更改他/她的密碼。</p><p>它允許用户執行其他活動，例如設置帳户到期日期，到期後設置密碼失效，顯示帳户過期信息，設置密碼更改前的最小和最大天數以及設置到期警告天數。</p><h4 id="如何使用-chage-命令執行此操作" tabindex="-1">如何使用 chage 命令執行此操作 <a class="header-anchor" href="#如何使用-chage-命令執行此操作" aria-label="Permalink to “如何使用 chage 命令執行此操作”">​</a></h4><p>讓我們在 <code>chage</code> 命令的幫助下，通過添加 <code>-d</code> 選項執行此操作。</p><p>為了測試這一點，讓我們創建一個新用户帳户，看看它是如何工作的。我們將創建一個名為 <code>thanu</code> 的用户帳户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># useradd -c &quot;2g Editor - Thanisha M&quot; thanu &amp;&amp; passwd thanu</span></span>
<span class="line"><span>Changing password for user thanu.</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span></code></pre></div><p>要實現這一點，請使用 <code>chage</code> 命令將用户的上次密碼更改日期設置為 0。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chage -d 0 thanu</span></span>
<span class="line"><span></span></span>
<span class="line"><span># chage -l thanu</span></span>
<span class="line"><span>Last password change : Jul 18, 2018</span></span>
<span class="line"><span>Password expires : never</span></span>
<span class="line"><span>Password inactive : never</span></span>
<span class="line"><span>Account expires : never</span></span>
<span class="line"><span>Minimum number of days between password change : 0</span></span>
<span class="line"><span>Maximum number of days between password change : 99999</span></span>
<span class="line"><span>Number of days of warning before password expires : 7</span></span></code></pre></div><p>當我第一次嘗試使用此用户登錄系統時，它要求我設置一個新密碼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>login as: thanu</span></span>
<span class="line"><span>[email protected]&#39;s password:</span></span>
<span class="line"><span>You are required to change your password immediately (root enforced)</span></span>
<span class="line"><span>WARNING: Your password has expired.</span></span>
<span class="line"><span>You must change your password now and login again!</span></span>
<span class="line"><span>Changing password for user thanu.</span></span>
<span class="line"><span>Changing password for thanu.</span></span>
<span class="line"><span>(current) UNIX password:</span></span>
<span class="line"><span>New password:</span></span>
<span class="line"><span>Retype new password:</span></span>
<span class="line"><span>passwd: all authentication tokens updated successfully.</span></span>
<span class="line"><span>Connection to localhost closed.</span></span></code></pre></div><hr>`,29)),i("p",null,[s[5]||(s[5]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/how-to-force-user-to-change-password-on-next-login-in-linux/"},{default:p(()=>[...s[4]||(s[4]=[a("https://www.2daygeek.com/how-to-force-user-to-change-password-on-next-login-in-linux/",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/prakash/"},{default:p(()=>[...s[6]||(s[6]=[a("Prakash Subramanian",-1)])]),_:1}),s[11]||(s[11]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 譯者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:p(()=>[...s[8]||(s[8]=[a("MjSeven",-1)])]),_:1}),s[13]||(s[13]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[16]||(s[16]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[14]||(s[14]=[a("LCTT",-1)])]),_:1}),s[17]||(s[17]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[15]||(s[15]=[a("Linux中國",-1)])]),_:1}),s[18]||(s[18]=a(" 榮譽推出",-1))])])}const y=t(h,[["render",u]]);export{x as __pageData,y as default};
